UPDATE payment_callback SET version=#{version},status=#{status},updated_at=#{updatedAt},next_attempt_at=#{nextAttemptAt},failures=#{failures},query_version=#{queryVersion},reason=#{reason},requested_by=#{requestedBy},request_reason=#{requestReason}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND event_id=#{eventId} AND payload_digest=#{payloadDigest} AND target_digest=#{targetDigest}
    AND payment_kind=#{kind} AND authorization_id=#{authorizationId} AND command_digest=#{commandDigest} AND source_revision=#{sourceRevision} AND received_at=#{receivedAt}
